// MCP tools for batch 79 (3-Nov-2026): picture frame sizing and label / wrap sizing for bottles, cans and takeaway cups.
// The tables and geometry come from src/tools_core79.js (generated by gen_tools_core.py from tool-gap-2026-10/newtools/
// mockup-core-69.js, mockup-core-73.js, mockup-core-79a.js, mockup-core-79c.js) — one source of truth with the /tools/ pages
// frame-mockup, bottle-mockup, can-mockup and coffee-cup-mockup. Stateless: no D1/R2, no fetch.
import { MGD79A as FA, MGD79C as FC } from "./tools_core79.js";

const T = "https://madegooddesigns.com/tools";
const ok = (text, structuredContent) => ({ content: [{ type: "text", text }], structuredContent });
const err = (text) => ({ content: [{ type: "text", text }], isError: true });
const str = (x, max) => (typeof x === "string" ? x : x == null ? "" : String(x)).slice(0, max);
const RO = (title) => ({ title, readOnlyHint: true, destructiveHint: false, openWorldHint: false });
const num = (v) => (v === undefined || v === null || v === "" ? undefined : Number(v));
const fin = (v) => Number.isFinite(num(v));
const IN = 25.4, PI = Math.PI;
const r1 = (v) => Math.round(v * 10) / 10, r2 = (v) => Math.round(v * 100) / 100;
const FSIZES = Object.keys(FA.FRAME_SIZES), LUNIT = { in: IN, cm: 10, mm: 1 };
const fmtIn = (p) => `${r2(p[0])} × ${r2(p[1])} in (${r1(p[0] * 2.54)} × ${r1(p[1] * 2.54)} cm)`;

export const TOOL_DEFS = [
  {
    name: "get_frame_size",
    description: "Use when framing a print, poster or photo: from the print size (8 × 10 to 24 × 36 in, A4 to A1, or custom), the mat width and the frame moulding width, gives the frame size to buy (print + 2 × mat), the mat opening (1/8 in smaller each side so the mat overlaps the print), and the outside size on the wall, in inches and cm.",
    inputSchema: {
      type: "object",
      properties: {
        size: { type: "string", enum: FSIZES, description: "Print size (default 16x20)." },
        width: { type: "number", description: "Custom print size (with height, instead of size)." },
        height: { type: "number" },
        unit: { type: "string", enum: Object.keys(LUNIT), description: "For width/height (default in)." },
        orientation: { type: "string", enum: ["portrait", "landscape"] },
        mat: { type: "number", description: "Mat border, in (0-4, default 2; 0 = no mat)." },
        moulding: { type: "number", description: "Frame face width, in (0.5-2.5, default 1)." },
      },
    },
    annotations: RO("Frame size"),
  },
  {
    name: "calc_label_wrap",
    description: "Use when sizing a label or wrap for packaging: bottle (wine, beer, soda, dropper, pump, steel), can (12 oz standard / sleek / slim, 250 ml, 16 oz) or takeaway cup (8 / 12 / 16 oz, ceramic), or a custom size. Gives circumference = π × d, label width for a coverage %, the width seen from the front and, for cups, the unrolled cone sector (outer / inner radius, angle, arc lengths).",
    inputSchema: {
      type: "object",
      properties: {
        container: { type: "string", enum: ["bottle", "can", "cup"], description: "Default bottle." },
        type: { type: "string", description: "Bottle / can / cup type key (default wine, std12, paper12; a wrong key lists them)." },
        diameter: { type: "number", description: "Custom bottle / can body, mm." },
        height: { type: "number", description: "Custom: label zone (bottle), print band (can) or cup height, mm." },
        rim: { type: "number", description: "Custom cup rim diameter, mm." },
        base: { type: "number", description: "Custom cup base diameter, mm." },
        coverage: { type: "number", description: "% of the way round, 10-105 (default: bottle 45, can and cup 100)." },
        label_height: { type: "number", description: "Bottle: % of the label zone, 15-100 (default 55)." },
      },
    },
    annotations: RO("Label wrap"),
  },
];

export const NEXT79 = {
  get_frame_size: "Next step: open the frame mockup link to see the print framed on a wall at this size, with the mat and a gallery-wall layout.",
  calc_label_wrap: "Next step: open the bottle mockup link (or the can / coffee cup mockup) to wrap your label round the real profile and download the flat print file.",
};

// ---- picture frame
function frameSize(a) {
  if (a.size !== undefined && !FSIZES.includes(a.size)) return err("size must be one of: " + FSIZES.join(", ") + " (or give width and height).");
  if (a.unit !== undefined && !LUNIT[a.unit]) return err("unit must be in, cm or mm.");
  if (a.orientation !== undefined && !["portrait", "landscape"].includes(a.orientation)) return err("orientation must be portrait or landscape.");
  if (a.mat !== undefined && !(fin(a.mat) && num(a.mat) >= 0 && num(a.mat) <= 4)) return err("mat must be 0-4 in.");
  if (a.moulding !== undefined && !(fin(a.moulding) && num(a.moulding) >= 0.5 && num(a.moulding) <= 2.5)) return err("moulding must be 0.5-2.5 in.");
  const mat = a.mat !== undefined ? num(a.mat) : 2, mould = a.moulding !== undefined ? num(a.moulding) : 1, orient = a.orientation || "portrait";
  let fo, label;
  if (a.width !== undefined || a.height !== undefined) {
    if (a.size !== undefined) return err("Give size or width + height, not both.");
    if (!(fin(a.width) && fin(a.height) && num(a.width) > 0 && num(a.height) > 0)) return err("width and height must both be numbers above 0.");
    const k = LUNIT[a.unit || "in"] / IN; let w = num(a.width) * k, h = num(a.height) * k;
    if (w < 2 || h < 2 || w > 80 || h > 80) return err("Custom print must be 2-80 in (5-200 cm) on each side.");
    if (orient === "landscape" && w < h || orient === "portrait" && w > h) [w, h] = [h, w];
    // same convention as frameOuter in mockup-core-79a.js (frame = print + 2 mat; opening 1/8 in in each side; 1/4 in rabbet each side)
    fo = { art: [w, h], frame: [w + 2 * mat, h + 2 * mat], opening: mat > 0 ? [w - 0.25, h - 0.25] : [w, h], outer: [w + 2 * mat + 2 * mould - 0.5, h + 2 * mat + 2 * mould - 0.5] };
    label = `${r2(num(a.width))} × ${r2(num(a.height))} ${a.unit || "in"}`;
  } else {
    const key = a.size || "16x20"; fo = FA.frameOuter(key, orient, mat, mould);
    label = /x/.test(key) ? key.replace("x", " × ") + " in" : key.toUpperCase();
  }
  const fr = fo.frame.map(r2);
  const page = `${T}/frame-mockup/`;
  const lines = [`**${label} print${mat ? ` with a ${mat} in mat` : ", no mat"}: buy a ${fmtIn(fr)} frame; about ${fmtIn(fo.outer)} outside with a ${mould} in moulding.**`,
    mat ? `Mat opening ${fmtIn(fo.opening)}: 1/8 in smaller than the print on every side, so the mat holds the edges.` : "No mat: the print sits straight behind the glass (frame size = print size).",
    "Frames are sold by the size of the picture they hold (the frame size above), not by their outside size.",
    "Outside size = frame size + 2 × moulding − 1/2 in (the moulding's 1/4 in rabbet lip covers the edge of the mat on each side).",
    "See it framed on a wall: " + page];
  return ok(lines.join("\n"), { print_in: fo.art.map(r2), mat_in: mat, moulding_in: mould, frame_in: fr, frame_cm: fr.map((v) => r1(v * 2.54)), mat_opening_in: mat ? fo.opening.map(r2) : null,
    outer_in: fo.outer.map(r2), outer_cm: fo.outer.map((v) => r1(v * 2.54)), orientation: orient, page });
}

// ---- label wrap
function labelWrap(a) {
  const cont = a.container || "bottle";
  if (!["bottle", "can", "cup"].includes(cont)) return err("container must be bottle, can or cup.");
  const TAB = { bottle: FC.BOTTLES, can: FC.CANS, cup: FC.CUPS }[cont], keys = Object.keys(TAB);
  const custom = cont === "cup" ? ["rim", "base", "height"] : ["diameter", "height"];
  const given = ["diameter", "height", "rim", "base"].filter((k) => a[k] !== undefined);
  if (a.type !== undefined && !keys.includes(a.type)) return err(`type for ${cont} must be one of: ${keys.join(", ")}.`);
  if (given.length && a.type !== undefined) return err("Give a type or a custom size, not both.");
  if (given.some((k) => !custom.includes(k))) return err(`Custom ${cont} takes ${custom.join(", ")} (mm).`);
  if (given.length && !custom.every((k) => fin(a[k]) && num(a[k]) >= 5 && num(a[k]) <= 1000)) return err(`Custom ${cont} needs ${custom.join(", ")}, each 5-1000 mm.`);
  if (cont === "cup" && given.length && !(num(a.rim) > num(a.base))) return err("rim must be wider than base (a cup tapers).");
  if (a.coverage !== undefined && !(fin(a.coverage) && num(a.coverage) >= 10 && num(a.coverage) <= 105)) return err("coverage must be 10-105 %.");
  if (a.label_height !== undefined && (cont !== "bottle" || !(fin(a.label_height) && num(a.label_height) >= 15 && num(a.label_height) <= 100))) return err("label_height is for bottles only: 15-100 % of the label zone.");
  const cov = (a.coverage !== undefined ? num(a.coverage) : cont === "bottle" ? 45 : 100) / 100, bleed = 1.5;
  const page = `${T}/${{ bottle: "bottle-mockup", can: "can-mockup", cup: "coffee-cup-mockup" }[cont]}/`;
  if (cont === "cup") {
    const c = given.length ? { name: `Custom cup (rim Ø ${num(a.rim)}, base Ø ${num(a.base)}, ${num(a.height)} mm tall)`, top: num(a.rim), bot: num(a.base), h: num(a.height) } : TAB[a.type || "paper12"];
    const s = FC.cupSector(c), ang = s.ang * 180 / PI * cov, outerArc = PI * c.top * cov, innerArc = PI * c.bot * cov;
    const chord = 2 * s.Ro * Math.sin(Math.min(PI, s.ang * cov / 2)), depth = s.Ro - s.Ri * Math.cos(Math.min(PI, s.ang * cov / 2));
    const lines = [`**${c.name}: rim circumference π × ${c.top} = ${s.rim_circ_mm} mm, base π × ${c.bot} = ${s.base_circ_mm} mm. The flat print is a curved sector (an unrolled cone), not a rectangle.**`,
      `Sector: outer radius ${s.outer_mm} mm (the rim edge), inner radius ${s.inner_mm} mm (the base edge), slant height ${s.slant_mm} mm; ${r1(s.angle_deg)}° for a full wrap.`,
      `At ${Math.round(cov * 100)}% coverage: ${r1(ang)}°, outer arc ${r1(outerArc)} mm, inner arc ${r1(innerArc)} mm; the template needs about ${r1(chord)} × ${r1(depth)} mm of paper.`,
      `From the front you see half the way round: ${r1(PI * c.top / 2)} mm of the rim (${c.top} mm wide).`,
      "Wrap the cup and download the flat print file: " + page];
    return ok(lines.join("\n"), { container: cont, type: given.length ? "custom" : a.type || "paper12", name: c.name, rim_mm: c.top, base_mm: c.bot, height_mm: c.h, rim_circumference_mm: s.rim_circ_mm, base_circumference_mm: s.base_circ_mm,
      coverage_pct: Math.round(cov * 100), sector: { outer_radius_mm: s.outer_mm, inner_radius_mm: s.inner_mm, slant_mm: s.slant_mm, full_angle_deg: s.angle_deg, angle_deg: r1(ang), outer_arc_mm: r1(outerArc), inner_arc_mm: r1(innerArc), paper_mm: [r1(chord), r1(depth)] }, page });
  }
  let name, d, zone, hLabel;
  if (cont === "bottle") {
    const lh = (a.label_height !== undefined ? num(a.label_height) : 55) / 100;
    if (given.length) { name = `Custom bottle (Ø ${num(a.diameter)} mm, ${num(a.height)} mm label zone)`; d = num(a.diameter); zone = num(a.height); }
    else { const L = FC.bottleLabel({ type: a.type || "wine", labelw: cov * 100, labelh: lh * 100 }), B = FC.BOTTLES[a.type || "wine"]; name = L.name; d = L.d; zone = B.body[1] - B.body[0]; }
    hLabel = zone * lh;
  } else {
    if (given.length) { name = `Custom can (Ø ${num(a.diameter)} mm, ${num(a.height)} mm print band)`; d = num(a.diameter); zone = hLabel = num(a.height); }
    else { const w = FC.canWrap({ size: a.type || "std12" }); name = w.c.name + ` (Ø ${w.c.d} × ${w.c.h} mm)`; d = w.c.d; zone = hLabel = w.h_mm; }
  }
  const C = PI * d, w = C * cov, vis = Math.min(w, C / 2), proj = d * Math.sin(Math.min(PI / 2, PI * cov)), overlap = Math.max(0, w - C);
  const px = [Math.round((w + 2 * bleed) / IN * 300), Math.round((hLabel + 2 * bleed) / IN * 300)];
  const lines = [`**${name}: circumference π × ${r1(d)} = ${r1(C)} mm. A label ${r1(w)} × ${r1(hLabel)} mm goes ${Math.round(cov * 100)}% of the way round (${Math.round(Math.min(360, 360 * cov))}°)${overlap > 0 ? `, overlapping itself by ${r1(overlap)} mm` : ""}.**`,
    `From the front you see ${r1(vis)} mm of it (at most half the circumference, ${r1(C / 2)} mm), which looks ${r1(proj)} mm wide${cov >= 1 ? "; the seam sits at the back" : ""}.`,
    cont === "bottle" ? `Label zone (straight body) ${r1(zone)} mm tall; the label is ${Math.round(hLabel / zone * 100)}% of it.` : `Print band = the straight body, ${r1(hLabel)} mm tall; check your can maker's template before print.`,
    `Print file with ${bleed} mm bleed: ${px[0]} × ${px[1]} px at 300 DPI.`, "Wrap it in the mockup and download the flat print: " + page];
  return ok(lines.join("\n"), { container: cont, type: given.length ? "custom" : a.type || (cont === "bottle" ? "wine" : "std12"), name, diameter_mm: r1(d), circumference_mm: r1(C), coverage_pct: Math.round(cov * 100),
    label_mm: [r1(w), r1(hLabel)], degrees: Math.round(Math.min(360, 360 * cov)), overlap_mm: r1(overlap), front_visible_arc_mm: r1(vis), front_apparent_width_mm: r1(proj), zone_mm: r1(zone), bleed_mm: bleed, px300: px, page });
}

const HANDLERS = { get_frame_size: frameSize, calc_label_wrap: labelWrap };
const NAMES = new Set(TOOL_DEFS.map((t) => t.name));
export function isTools79Tool(name) { return NAMES.has(name); }
export async function callTools79Tool(name, a) {
  a = a && typeof a === "object" ? a : {};
  try {
    if (HANDLERS[name]) return HANDLERS[name](a);
  } catch (e) {
    return err(`${name} failed: ${str(e && e.message, 300)}`);
  }
  return err("Unknown tool: " + name);
}
